<?php
declare(strict_types=1);
require dirname(__DIR__).'/bin/common.php';
$c=cliConfig();
if($c['environment']!=='local'||!str_starts_with($c['database']['name'],'dloop_test_local_mode_'))throw new RuntimeException('New isolated fixture required.');
$db=\DLoop\Database::connect($c);$inventory=new \DLoop\Inventory($db,'1');$checks=0;
$check=static function(bool $ok,string $why)use(&$checks){if(!$ok)throw new RuntimeException($why);$checks++;};
$save=static function(array $a)use($inventory){$s=$inventory->snapshot();return $inventory->mutate(['revision'=>$s['revision'],'action'=>$a],bin2hex(random_bytes(16)));};
$reject=static function(array $a,string $code)use($save,$check){try{$save($a);throw new RuntimeException('Expected rejection');}catch(\DLoop\HttpError $e){$check($e->errorCode===$code,'Wrong rejection: '.$e->errorCode);}};
$suffix=bin2hex(random_bytes(3));
$s=$save(['type'=>'brand','brand'=>['name'=>'Numaker '.$suffix,'active'=>true,'defaultTare'=>'193','defaultTareVerified'=>false]]);
$brand=array_values(array_filter($s['state']['brands'],fn($b)=>$b['name']==='Numaker '.$suffix))[0];
$check($brand['defaultTare']===193.0&&!$brand['defaultTareVerified'],'Brand provisional value retained');
$s=$save(['type'=>'brand','brand'=>['name'=>'Other '.$suffix,'active'=>true]]);
$other=array_values(array_filter($s['state']['brands'],fn($b)=>$b['name']==='Other '.$suffix))[0];$check($other['defaultTare']===null,'No universal fallback');
$template=['name'=>'Numaker White UNVERIFIED '.$suffix,'brandId'=>$brand['id'],'material'=>'PLA+','colorName'=>'White','color'=>'#ffffff','spoolType'=>'Unknown','capacity'=>'1000','initial'=>'982','remaining'=>'982','mode'=>'manual','registrationKind'=>'partial','profileId'=>null,'tareOverride'=>null,'location'=>'','catalogueId'=>null,'estimateNote'=>'UNVERIFIED: gross without cover 1175 g; provisional brand tare 193 g; cover excluded.'];
$s=$save(['type'=>'add','spool'=>$template,'confirmed'=>true]);$spool=array_values(array_filter($s['state']['spools'],fn($p)=>$p['name']===$template['name']))[0];
$check($spool['remaining']===982.0&&$spool['tare']===193.0&&$spool['tareProvisional']&&!$spool['measured'],'Manual estimated balance and brand inheritance');
$check((int)$db->query("SELECT COUNT(*) FROM measurements WHERE spool_id=".$db->quote($spool['id']))->fetchColumn()===0,'No verified measurement row');
$reject(['type'=>'add','spool'=>array_replace($template,['brandId'=>$other['id']]),'confirmed'=>true],'unknown_tare');
$gross=array_replace($template,['mode'=>'gross','gross'=>'1175']);unset($gross['remaining']);
$reject(['type'=>'add','spool'=>$gross,'confirmed'=>true],'unverified_tare');
$s=$save(['type'=>'brand','brand'=>array_replace($brand,['defaultTare'=>'210'])]);
$old=array_values(array_filter($s['state']['spools'],fn($p)=>$p['id']===$spool['id']))[0];$check($old['tare']===193.0&&$old['remaining']===982.0,'Default edit preserves existing snapshot/balance');
$s=$save(['type'=>'add','spool'=>array_replace($template,['name'=>'Override '.$suffix,'tareOverride'=>'220','tareOverrideVerified'=>false]),'confirmed'=>true]);
$override=array_values(array_filter($s['state']['spools'],fn($p)=>$p['name']==='Override '.$suffix))[0];$check($override['tare']===220.0&&$override['tareProvisional'],'Per-spool override wins');
$check($override['code']!==$spool['code'],'Automatic physical-spool codes unique');
try{$db->prepare('UPDATE spools SET code=? WHERE id=?')->execute([$spool['code'],$override['id']]);throw new RuntimeException('Duplicate code accepted');}catch(PDOException $e){$check((int)$e->errorInfo[1]===1062,'DB code uniqueness');}
$s=$save(['type'=>'profile','profile'=>['brandId'=>$brand['id'],'spoolType'=>'Cardboard test','capacity'=>'1000','tare'=>'175','verified'=>false,'active'=>true,'notes'=>'Test model']]);
$profile=array_values(array_filter($s['state']['profiles'],fn($p)=>$p['brandId']===$brand['id']))[0];
$s=$save(['type'=>'add','spool'=>array_replace($template,['name'=>'Model '.$suffix,'spoolType'=>$profile['spoolType'],'profileId'=>$profile['id']]),'confirmed'=>true]);
$model=array_values(array_filter($s['state']['spools'],fn($p)=>$p['name']==='Model '.$suffix))[0];$check($model['tare']===175.0&&$model['tareProvisional'],'Model overrides brand without verification fabrication');
$before=count($s['state']['spools']);
$s=$save(['type'=>'tag-url','id'=>$spool['id'],'version'=>$spool['version'],'confirmed'=>true,'replace'=>false]);
$first=array_values(array_filter($s['state']['spools'],fn($p)=>$p['id']===$spool['id']))[0];$token=$first['tagToken'];$check((bool)preg_match('/^[a-f0-9]{48}$/D',$token),'Opaque tag token');
$s=$save(['type'=>'tag-url','id'=>$first['id'],'version'=>$first['version'],'confirmed'=>true,'replace'=>true]);$replacement=array_values(array_filter($s['state']['spools'],fn($p)=>$p['id']===$spool['id']))[0];
$check($replacement['tagToken']!==$token&&count($s['state']['spools'])===$before,'Tag replacement does not create spools');
$q=$db->prepare('SELECT COUNT(*) FROM spools WHERE tag_token=?');$q->execute([$token]);$check((int)$q->fetchColumn()===0,'Old URL identity invalidated');
$uid1='04'.strtoupper(bin2hex(random_bytes(6)));$uid2='04'.strtoupper(bin2hex(random_bytes(6)));
$s=$save(['type'=>'link','id'=>$replacement['id'],'versions'=>[$replacement['id']=>$replacement['version']],'uid'=>$uid1,'confirmed'=>true]);
$replacement=array_values(array_filter($s['state']['spools'],fn($p)=>$p['id']===$spool['id']))[0];
$s=$save(['type'=>'link','id'=>$replacement['id'],'versions'=>[$replacement['id']=>$replacement['version']],'uid'=>$uid2,'confirmed'=>true]);
$check(count($s['state']['spools'])===$before,'Hardware tag replacement keeps spool');
$q=$db->prepare('SELECT uid FROM nfc_tags WHERE spool_id=?');$q->execute([$replacement['id']]);$check($q->fetchColumn()===$uid2,'Hardware UID association replaced');
$unlinked=array_values(array_filter($s['state']['spools'],fn($p)=>$p['id']===$replacement['id']))[0];
$reject(['type'=>'tag-unlink','id'=>$unlinked['id'],'version'=>$unlinked['version'],'confirmed'=>false],'confirmation_required');
$reject(['type'=>'tag-unlink','id'=>$unlinked['id'],'version'=>$unlinked['version']+1,'confirmed'=>true],'version_conflict');
$s=$save(['type'=>'tag-unlink','id'=>$unlinked['id'],'version'=>$unlinked['version'],'confirmed'=>true]);
$after=array_values(array_filter($s['state']['spools'],fn($p)=>$p['id']===$unlinked['id']))[0];
$check($after['tagToken']===null&&$after['nfc']==='','Unlink clears both tag associations');
$check(count($s['state']['spools'])===$before&&$after['remaining']===982.0&&$after['tare']===193.0&&$after['tareProvisional']&&!$after['measured'],'Unlink preserves inventory and verification');
echo "PASS: $checks brand tare/snapshot/provisional/manual-safety, code uniqueness, model/override and URL/hardware tag replacement checks. Isolated test database only.\n";
